    fr: 'La transaction a expiré avant confirmation. Votre tirage est sauvé localement -- aucun frais.',
    bn: '\u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4\u0995\u09B0\u09A3\u09C7\u09B0 \u0986\u0997\u09C7\u0987 \u09B2\u09C7\u09A8\u09A6\u09C7\u09A8 \u09AC\u09BE\u09A4\u09BF\u09B2 \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09BE\u09A0 \u09B8\u0982\u09B0\u0995\u09CD\u09B7\u09BF\u09A4 -- \u0995\u09CB\u09A8\u09CB \u09AB\u09BF \u0995\u09BE\u099F\u09BE \u09B9\u09AF\u09BC\u09A8\u09BF\u0964',
    pt: 'A transação caiu antes da confirmação. Sua leitura está salva localmente -- nada foi cobrado.',
    ru: '\u0422\u0440\u0430\u043D\u0437\u0430\u043A\u0446\u0438\u044F \u043D\u0435 \u0434\u043E\u0436\u0434\u0430\u043B\u0430\u0441\u044C \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F. \u0420\u0430\u0441\u043A\u043B\u0430\u0434 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E -- \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u043D\u0435 \u0441\u043F\u0438\u0441\u0430\u043D\u044B.',
