    hi: '\u092A\u094D\u0930\u0924\u093F\u0926\u093F\u0928 3 \u092E\u0941\u092B\u094D\u0924 \u092A\u094D\u0930\u0936\u094D\u0928 \u0909\u092A\u0932\u092C\u094D\u0927 \u0939\u0948\u0902\u0964 \u0926\u0948\u0928\u093F\u0915 \u0915\u093E\u0930\u094D\u0921 \u0939\u092E\u0947\u0936\u093E \u092E\u0941\u092B\u094D\u0924 \u0939\u0948\u0964',
    es: 'Los exploradores reciben 3 consultas diarias. Tu carta diaria siempre es gratis.',
    ar: '\u064A\u062D\u0635\u0644 \u0627\u0644\u0628\u0627\u062D\u062B \u0639\u0644\u0649 3 \u0627\u0633\u062A\u0641\u0633\u0627\u0631\u0627\u062A \u0645\u062C\u0627\u0646\u064A\u0629 \u064A\u0648\u0645\u064A\u0627\u064B. \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u064A\u0648\u0645 \u062F\u0627\u0626\u0645\u0627\u064B \u0645\u062C\u0627\u0646\u064A\u0629.',
    fr: 'Les explorateurs bénéficient de 3 tirages par jour. Votre carte du jour reste toujours gratuite.',
    bn: '\u09A6\u09C8\u09A8\u09BF\u0995 \u09E9\u099F\u09BF \u09AC\u09BF\u09A8\u09BE\u09AE\u09C2\u09B2\u09CD\u09AF\u09C7 \u09AA\u09CD\u09B0\u09B6\u09CD\u09A8\u0964 \u09A6\u09C8\u09A8\u09BF\u0995 \u0915\u093E\u0930\u094D\u0921 \u09B8\u09B0\u09CD\u09AC\u09A6\u09BE \u09AE\u09C1\u09AB\u09A4\u0964',
    pt: 'Exploradores recebem 3 consultas diárias gratuitas. Sua carta diária é sempre gratuita.',
    ru: '\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u043E 3 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u044B\u0445 \u0437\u0430\u043F\u0440\u043E\u0441\u0430 \u0432 \u0434\u0435\u043D\u044C. \u0414\u043D\u0435\u0432\u043D\u043E\u0439 \u043A\u043E\u043D\u0441\u0435\u043D\u0441\u0443\u0441 \u0432\u0441\u0435\u0433\u0434\u0430 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u0435\u043D.',
    id: 'Pencari mendapatkan 3 pertanyaan gratis setiap hari. Kartu harian selalu gratis.',
