    hi: '\u0906\u092A\u0915\u0940 \u0926\u0948\u0928\u093F\u0915 \u0928\u093F\u0903\u0936\u0941\u0932\u094D\u0915 \u0938\u0940\u092E\u093E \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u0917\u0908 \u0939\u0948\u0964 \u0906\u092A\u0915\u0947 \u0916\u093E\u0924\u0947 \u0938\u0947 {cost} SKR \u0915\u093E\u091F\u0947 \u091C\u093E\u090F\u0902\u0917\u0947\u0964',
    es: 'Tu cuota diaria gratuita se ha agotado. Esta tirada deducir\u00E1 {cost} SKR de tu saldo.',
