    pt: 'Sua cota di\u00E1ria gratuita est\u00E1 esgotada. Este lan\u00E7amento deduzir\u00E1 {cost} SKR do seu saldo.',
    ru: '\u0411\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u044B\u0435 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u044B \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u044B. \u0414\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0440\u0438\u0442\u0443\u0430\u043B\u0430 \u043F\u043E\u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F {cost} SKR \u0441 \u0432\u0430\u0448\u0435\u0433\u043E \u0431\u0430\u043B\u0430\u043D\u0441\u0430.',
