    pt: 'Selecione o dialeto sagrado para a comunh\u00E3o com o or\u00E1culo',
    ru: '\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0430\u043A\u0440\u0430\u043B\u044C\u043D\u044B\u0439 \u0434\u0438\u0430\u043B\u0435\u043A\u0442 \u0434\u043B\u044F \u0435\u0434\u0438\u043D\u0435\u043D\u0438\u044F \u0441 \u043E\u0440\u0430\u043A\u0443\u043B\u043E\u043C',
