    fr: 'PRIVIL\u00C8GE SEEKER GENESIS SBT',
    bn: '\u09B8\u09BF\u0995\u09BE\u09B0 \u099C\u09C7\u09A8\u09C7\u09B8\u09BF\u09B8 SBT \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE',
