  "seeker_sbt_privilege_desc": {
    en: 'Free daily readings are an exclusive privilege of Solana Seeker Genesis SBT holders.\n\nPart the veil by offering SKR or SOL to commune with Arkana.',
    zh: '\u6BCF\u65E5\u514D\u8D39\u89E3\u724C\u662F Solana Seeker Genesis SBT \u6301\u6709\u8005\u7684\u4E13\u5C5E\u7279\u6743\u3002\n\n\u4F9B\u5949 SKR \u6216 SOL \u4EE5\u4E0E Arkana \u6C9F\u901A\u3002',
    hi: '\u0926\u0948\u0928\u093F\u0915 \u092E\u0941\u092B\u094D\u0924 \u0935\u093E\u091A\u0928 Solana Seeker Genesis SBT \u0927\u093E\u0930\u0915\u094B\u0902 \u0915\u093E \u090F\u0915 \u0935\u093F\u0936\u0947\u0937 \u0905\u0927\u093F\u0915\u093E\u0930 \u0939\u0948\u0964\n\nArkana \u0938\u0947 \u0938\u0902\u0935\u093E\u0926 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F SKR \u092F\u093E SOL \u0915\u0940 \u092D\u0947\u0902\u091F \u0915\u0930\u0947\u0902\u0964',
    es: 'Las lecturas diarias gratuitas son un privilegio exclusivo de los poseedores de Seeker Genesis SBT.\n\nOfrenda SKR o SOL para comulgar con Arkana.',
    ar: '\u0627\u0644\u0642\u0631\u0627\u0621\u0627\u062A \u0627\u0644\u064A\u0648\u0645\u064A\u0629 \u0627\u0644\u0645\u062C\u0627\u0646\u064A\u0629 \u0647\u064A \u0627\u0645\u062A\u064A\u0627\u0632 \u062D\u0635\u0631\u064A \u0644\u062D\u0627\u0645\u0644\u064A Seeker Genesis SBT.\n\n\u0642\u062F\u0645 SKR \u0623\u0648 SOL \u0644\u0644\u062A\u0648\u0627\u0635\u0644 \u0645\u0639 Arkana.',
    fr: 'Les tirages quotidiens gratuits sont un privil\u00E8ge r\u00E9serv\u00E9 aux d\u00E9tenteurs de Seeker Genesis SBT.\n\nOffrez des SKR ou des SOL pour communier avec Arkana.',
    bn: '\u09A6\u09C8\u09A8\u09BF\u0995 \u09AB\u09CD\u09B0\u09BF \u09AA\u09BE\u09A0 Solana Seeker Genesis SBT \u09A7\u09BE\u09B0\u0995\u09A6\u09C7\u09B0 \u098F\u0995\u099F\u09BF \u09AC\u09BF\u09B6\u09C7\u09B7 \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE\u0964\n\nArkana-\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AF\u09CB\u0997\u09BE\u09AF\u09CB\u0997 \u0995\u09B0\u09A4\u09C7 SKR \u09AC\u09BE SOL \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09C1\u09A8\u0964',
    pt: 'As leituras di\u00E1rias gratuitas s\u00E3o privil\u00E9gio exclusivo dos detentores de Seeker Genesis SBT.\n\nOfere\u00E7a SKR ou SOL para comungar com a Arkana.',
    ru: '\u0411\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u044B\u0435 \u0434\u043D\u0435\u0432\u043D\u044B\u0435 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u044B -- \u044D\u043A\u0441\u043A\u043B\u044E\u0437\u0438\u0432\u043D\u0430\u044F \u043F\u0440\u0438\u0432\u0438\u043B\u0435\u0433\u0438\u044F \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0435\u0432 Seeker Genesis SBT.\n\n\u041F\u0440\u0438\u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0437\u0430\u0432\u0435\u0441\u0443, \u043F\u043E\u0436\u0435\u0440\u0442\u0432\u043E\u0432\u0430\u0432 SKR \u0438\u043B\u0438 SOL.',
    id: 'Pembacaan harian gratis adalah hak istimewa eksklusif bagi pemegang Seeker Genesis SBT.\n\nBuka tirai dengan mempersembahkan SKR atau SOL untuk berkomunikasi dengan Arkana.',
  },
