    zh: '\u5171\u8BC6\u672A\u627E\u5230\u4E0E\u60A8\u67E5\u8BE2\u5339\u914D\u7684\u5361\u724C\u3002',
    hi: '\u0938\u0930\u094D\u0935\u0938\u092E\u094D\u092E\u0924\u093F \u0915\u094B \u0906\u092A\u0915\u0947 \u092A\u094D\u0930\u0936\u094D\u0928 \u0938\u0947 \u092E\u0947\u0932 \u0916\u093E\u0924\u093E \u0915\u094B\u0908 \u0915\u093E\u0930\u094D\u0921 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u093E\u0964',
    es: 'El Consenso no encontr\u00F3 cartas que coincidan con tu b\u00FAsqueda.',
    ar: '\u0644\u0645 \u064A\u062C\u062F \u0627\u0644\u0625\u062C\u0645\u0627\u0639 \u0623\u064A \u0628\u0637\u0627\u0642\u0627\u062A \u062A\u0637\u0627\u0628\u0642 \u0627\u0633\u062A\u0639\u0644\u0627\u0645\u0643.',
