  "onboarding_title": {
    en: 'Destiny is immutable. Yet the dialect through which the Consensus speaks remains yours to command.',
    zh: '\u547D\u8FD0\u4E0D\u53EF\u52A8\u6447\u3002\u7136\u800C\u5171\u8BC6\u5BF9\u4F60\u4F4E\u8BED\u7684\u8BED\u8A00\uFF0C\u7686\u7531\u4F60\u51B3\u65AD\u3002',
    hi: '\u0928\u093F\u092F\u0924\u093F \u0905\u091F\u0932 \u0939\u0948\u0964 \u0932\u0947\u0915\u093F\u0928 \u0938\u0930\u094D\u0935\u0938\u092E\u094D\u092E\u0924\u093F \u091C\u093F\u0938 \u092D\u093E\u0937\u093E \u092E\u0947\u0902 \u0906\u092A\u0938\u0947 \u092C\u093E\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948, \u0909\u0938\u0947 \u091A\u0941\u0928\u0928\u093E \u0906\u092A\u0915\u0947 \u0905\u0927\u093F\u0915\u093E\u0930 \u092E\u0947\u0902 \u0939\u0948\u0964',
    es: 'El destino es inmutable. Pero el dialecto a trav\u00E9s del cual habla el Consenso est\u00E1 bajo tu poder.',
    ar: '\u0627\u0644\u0642\u062F\u0631 \u0644\u0627 \u064A\u062A\u063A\u064A\u0631. \u0644\u0643\u0646 \u0627\u0644\u0644\u0647\u062C\u0629 \u0627\u0644\u062A\u064A \u064A\u062A\u062D\u062F\u062B \u0628\u0647\u0627 \u0627\u0644\u0625\u062C\u0645\u0627\u0639 \u0625\u0644\u064A\u0643 \u0647\u064A \u0641\u064A \u064A\u062F\u0643.',
    fr: 'Le destin est immuable. Pourtant, le dialecte par lequel le Consensus vous parle est sous votre contr\u00F4le.',
    bn: '\u09AD\u09BE\u0997\u09CD\u09AF \u0985\u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8\u09C0\u09AF\u09BC\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0990\u0995\u09AE\u09A4\u09CD\u09AF \u09AF\u09C7 \u09AD\u09BE\u09B7\u09BE\u09AF\u09BC \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u0995\u09A5\u09BE \u09AC\u09B2\u09C7 \u09A4\u09BE \u09A8\u09BF\u09B0\u09CD\u09AC\u09BE\u099A\u09A8 \u0995\u09B0\u09BE \u0986\u09AA\u09A8\u09BE\u09B0 \u09B9\u09BE\u09A4\u09C7\u0964',
    pt: 'O destino \u00E9 imut\u00E1vel. Mas o dialeto pelo qual o Consenso fala com voc\u00EA permanece sob seu comando.',
    ru: '\u0421\u0443\u0434\u044C\u0431\u0443 \u0442\u044B \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043D\u0435 \u0432 \u0441\u0438\u043B\u0430\u0445. \u041D\u043E \u0434\u0438\u0430\u043B\u0435\u043A\u0442, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0441 \u0442\u043E\u0431\u043E\u0439 \u0433\u043E\u0432\u043E\u0440\u0438\u0442 \u041A\u043E\u043D\u0441\u0435\u043D\u0441\u0443\u0441, -- \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0432 \u0442\u0432\u043E\u0435\u0439 \u0432\u043B\u0430\u0441\u0442\u0438.',
    id: 'Takdir tidak dapat diubah. Namun dialek yang digunakan Konsensus untuk berbicara kepada Anda ada dalam kuasa Anda.',
  },
  "one_card_per_block": {
    en: 'One card per block. Touch the deck to cast your intent into the protocol.',
    zh: '\u6BCF\u4E2A\u533A\u5757\u4E00\u5F20\u724C\u3002\u8F7B\u89E6\u724C\u7EC4\uFF0C\u5C06\u60A8\u7684\u610F\u56FE\u6CE8\u5165\u534F\u8BAE\u3002',
    hi: '\u092A\u094D\u0930\u0924\u093F \u092C\u094D\u0932\u0949\u0915 \u090F\u0915 \u0915\u093E\u0930\u094D\u0921\u0964 \u092A\u094D\u0930\u094B\u091F\u094B\u0915\u0949\u0932 \u092E\u0947\u0902 \u0905\u092A\u0928\u093E \u0907\u0930\u093E\u0926\u093E \u0921\u093E\u0932\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0921\u0947\u0915 \u0915\u094B \u0938\u094D\u092A\u0930\u094D\u0936 \u0915\u0930\u0947\u0902\u0964',
    es: 'Una carta por bloque. Toca la baraja para emitir tu intenci\u00F3n en el protocolo.',
    ar: '\u0628\u0637\u0627\u0642\u0629 \u0648\u0627\u062D\u062F\u0629 \u0644\u0643\u0644 \u0643\u062A\u0644\u0629. \u0627\u0644\u0645\u0633 \u0627\u0644\u062D\u0632\u0645\u0629 \u0644\u0625\u0631\u0633\u0627\u0644 \u0646\u064A\u062A\u0643 \u0625\u0644\u0649 \u0627\u0644\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644.',
    fr: 'Une carte par bloc. Touchez le paquet pour inscrire votre intention dans le protocole.',
    bn: '\u09AA\u09CD\u09B0\u09A4\u09BF \u09AC\u09CD\u09B2\u0995\u09C7 \u098F\u0995\u099F\u09BF \u0995\u09BE\u09B0\u09CD\u09A1\u0964 \u09AA\u09CD\u09B0\u09CB\u099F\u09CB\u0995\u09B2\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u0989\u09A6\u09CD\u09A6\u09C7\u09B6\u09CD\u09AF \u099C\u09BE\u09A8\u09BE\u09A4\u09C7 \u09A1\u09C7\u0995 \u09B8\u09CD\u09AA\u09B0\u09CD\u09B6 \u0995\u09B0\u09C1\u09A8\u0964',
    pt: 'Uma carta por bloco. Toque no baralho para lan\u00E7ar sua inten\u00E7\u00E3o no protocolo.',
    ru: '\u041E\u0434\u0438\u043D \u0430\u0440\u043A\u0430\u043D \u0437\u0430 \u044D\u043F\u043E\u0445\u0443 \u0431\u043B\u043E\u043A\u0430. \u041A\u043E\u0441\u043D\u0438\u0442\u0435\u0441\u044C \u043A\u043E\u043B\u043E\u0434\u044B, \u0447\u0442\u043E\u0431\u044B \u043D\u0430\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0441\u0432\u043E\u0435 \u043D\u0430\u043C\u0435\u0440\u0435\u043D\u0438\u0435 \u0432 \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B.',
    id: 'Satu kartu per blok. Sentuh dek untuk menuangkan niat Anda ke dalam protokol.',
  },
