    hi: '\u092C\u093E\u091C\u093E\u0930 \u0915\u093E \u0936\u094B\u0930 \u092E\u0941\u091D\u0947 \u0938\u0902\u0930\u091A\u0928\u093E\u0924\u094D\u092E\u0915 \u0935\u093E\u0938\u094D\u0924\u0935\u093F\u0915\u0924\u093E \u0938\u0947 \u0915\u0939\u093E\u0901 \u0905\u0902\u0927\u093E \u0915\u0930 \u0930\u0939\u093E \u0939\u0948?',
