    bn: '\u09AC\u09BE\u099C\u09BE\u09B0\u09C7\u09B0 \u0997\u09CB\u09B2\u09AE\u09BE\u09B2 \u0986\u09AE\u09BE\u0995\u09C7 \u0995\u09BE\u09A0\u09BE\u09AE\u09CB\u0997\u09A4 \u09AC\u09BE\u09B8\u09CD\u09A4\u09AC\u09A4\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF \u0995\u09CB\u09A5\u09BE\u09AF\u09BC \u0985\u09A8\u09CD\u09A7 \u0995\u09B0\u099B\u09C7?',
