    bn: '\u0986\u09AE\u09BF \u098F\u0995\u099F\u09BF \u09B8\u0982\u09AF\u09CB\u0997\u09B8\u09CD\u09A5\u09B2\u09C7 \u09A6\u09BE\u0981\u09A1\u09BC\u09BF\u09AF\u09BC\u09C7 \u0986\u099B\u09BF\u0964 \u0986\u09AE\u09BE\u09B0 \u09B6\u0995\u09CD\u09A4\u09BF \u0995\u09CB\u09A5\u09BE\u09AF\u09BC \u09AC\u09BF\u09A8\u09BF\u09AF\u09BC\u09CB\u0997 \u0995\u09B0\u09BE \u0989\u099A\u09BF\u09A4?',
    pt: 'Estou em uma encruzilhada. Onde devo concentrar minha energia?',
