    hi: '\u0906\u091C \u0915\u093E \u092C\u094D\u0932\u0949\u0915 \u0938\u094D\u0925\u093E\u092F\u0940 \u0930\u0942\u092A \u0938\u0947 \u0926\u0930\u094D\u091C \u0939\u0948\u0964 \u0906\u0917\u0947 \u092E\u093E\u0930\u094D\u0917\u0926\u0930\u094D\u0936\u0928 \u0915\u0947 \u0932\u093F\u090F \u0928\u0940\u091A\u0947 \u0938\u094D\u092A\u094D\u0930\u0947\u0921 \u0915\u0930\u0947\u0902\u0964',
    es: 'El bloque de hoy est\u00E1 registrado permanentemente. Para consultar m\u00E1s al or\u00E1culo, echa una Tirada abajo.',
