  "unrevealed_desc": {
    en: 'This archetype has not been unveiled yet. Draw your Daily Consensus Block or cast a spread on the Altar to awaken this archetype.',
    zh: '\u8BE5\u539F\u578B\u5C1A\u672A\u663E\u73B0\u3002\u6BCF\u65E5\u5728\u796D\u575B\u62BD\u53D6\u5171\u8BC6\u533A\u5757\uFF0C\u6216\u63A8\u6F14\u724C\u9635\u4EE5\u5524\u9192\u6B64\u539F\u578B\u3002',
    hi: '\u092F\u0939 \u092E\u0942\u0932\u0930\u0942\u092A \u0905\u092D\u0940 \u0924\u0915 \u092A\u094D\u0930\u0915\u091F \u0928\u0939\u0940\u0902 \u0939\u0941\u0906 \u0939\u0948\u0964 \u0907\u0938\u0947 \u091C\u0917\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0926\u0948\u0928\u093F\u0915 \u0938\u0939\u092E\u0924\u093F \u092C\u094D\u0932\u0949\u0915 \u0932\u0947\u0902 \u092F\u093E \u0935\u0947\u0926\u0940 \u092A\u0930 \u0938\u094D\u092A\u094D\u0930\u0947\u0921 \u0915\u0930\u0947\u0902\u0964',
    es: 'Este arquetipo a\u00FAn no ha sido desvelado. Realiza el Bloque de Consenso Diario o echa una tirada en el Altar para despertarlo.',
    ar: '\u0644\u0645 \u064A\u062A\u0645 \u0627\u0644\u0643\u0634\u0641 \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u0646\u0645\u0648\u0630\u062C \u0628\u0639\u062F. \u0627\u0633\u062D\u0628 \u0643\u062A\u0644\u0629 \u0627\u0644\u0625\u062C\u0645\u0627\u0639 \u0627\u0644\u064A\u0648\u0645\u064A\u0629 \u0623\u0648 \u0642\u0645 \u0628\u0639\u0645\u0644 \u0633\u062D\u0628 \u0639\u0644\u0649 \u0627\u0644\u0645\u0630\u0628\u062D \u0644\u0625\u064A\u0642\u0627\u0638\u0647.',
    fr: 'Cet arch\u00E9type n\'a pas encore \u00E9t\u00E9 d\u00E9voil\u00E9. Tirez votre bloc de consensus quotidien ou effectuez un tirage sur l\'Autel pour l\'\u00E9veiller.',
    bn: '\u098F\u0987 \u0986\u09B0\u09CD\u0995\u09BF\u099F\u09BE\u0987\u09AA\u099F\u09BF \u098F\u0996\u09A8\u0993 \u0989\u09A8\u09CD\u09AE\u09CB\u099A\u09BF\u09A4 \u09B9\u09AF\u09BC\u09A8\u09BF\u0964 \u098F\u099F\u09BF\u0995\u09C7 \u099C\u09BE\u0997\u09CD\u09B0\u09A4 \u0995\u09B0\u09A4\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09A6\u09C8\u09A8\u09BF\u0995 \u0990\u0995\u09AE\u09A4\u09CD\u09AF \u09AC\u09CD\u09B2\u0995 \u0986\u0981\u0995\u09C1\u09A8 \u09AC\u09BE \u09AC\u09C7\u09A6\u09BF\u09A4\u09C7 \u098F\u0995\u099F\u09BF \u09B8\u09CD\u09AA\u09CD\u09B0\u09C7\u09A1 \u0995\u09B0\u09C1\u09A8\u0964',
    pt: 'Este arqu\u00E9tipo ainda n\u00E3o foi revelado. Tire seu Bloco de Consenso Di\u00E1rio ou lance uma tirada no Altar para despert\u00E1-lo.',
    ru: '\u042D\u0442\u043E\u0442 \u0430\u0440\u0445\u0435\u0442\u0438\u043F \u0435\u0449\u0435 \u043D\u0435 \u0431\u044B\u043B \u044F\u0432\u043B\u0435\u043D \u0432\u0430\u043C. \u0421\u043E\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u0435\u0436\u0435\u0434\u043D\u0435\u0432\u043D\u044B\u0439 \u043A\u043E\u043D\u0441\u0435\u043D\u0441\u0443\u0441 \u0438\u043B\u0438 \u0440\u0430\u0437\u043B\u043E\u0436\u0438\u0442\u0435 \u0430\u0440\u043A\u0430\u043D\u044B \u043D\u0430 \u0410\u043B\u0442\u0430\u0440\u0435, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0431\u0443\u0434\u0438\u0442\u044C \u0435\u0433\u043E.',
    id: 'Arketipe ini belum terungkap. Tarik Blok Konsensus Harian Anda atau tebarkan spread di Altar untuk membangkitkannya.',
  },
