    fr: 'Aucun portefeuille Solana compatible d\u00E9tect\u00E9 sur cet appareil. Installez Phantom ou Solflare.',
    bn: '\u098F\u0987 \u09A1\u09BF\u09AD\u09BE\u0987\u09B8\u09C7 \u0995\u09CB\u09A8\u09CB \u09B8\u09BE\u09AE\u099E\u09CD\u099C\u09B8\u09CD\u09AF\u09AA\u09C2\u09B0\u09CD\u09A3 \u0993\u09AF\u09BC\u09BE\u09B2\u09C7\u099F \u09B8\u09A8\u09BE\u0995\u09CD\u09A4 \u0995\u09B0\u09BE \u09AF\u09BE\u09AF\u09BC\u09A8\u09BF\u0964 \u09AA\u09CD\u09B2\u09C7 \u09B8\u09CD\u099F\u09CB\u09B0 \u09A5\u09C7\u0995\u09C7 \u09AB\u09CD\u09AF\u09BE\u09A8\u09CD\u099F\u09AE \u0987\u09A8\u09B8\u09CD\u099F\u09B2 \u0995\u09B0\u09C1\u09A8\u0964',
    pt: 'Nenhuma carteira compat\u00EDvel detectada neste dispositivo. Instale a Phantom ou Solflare da Play Store.',
    ru: '\u041D\u0430 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u043D\u0435 \u043E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D \u043A\u043E\u0448\u0435\u043B\u0435\u043A Solana. \u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 Phantom \u0438\u043B\u0438 Solflare \u0438\u0437 Google Play Store.',
